      {
        "date": "2026-04-25",
        "method": "알 수 없음",
        "content": "안녕하세요, 학원 수업 문의드리고자 연락드렸습니다.\n다름이 아니라 저희 아이가 현재 UWC East 5학년(G5)에 재학 중인데, 학원 등록 방법과 현재 수강 가능한 자리가 있는지 여쭈어보고 싶습니다.\n확인 부탁드립니다. 감사합니다."
      },
      {
        "date": "2026-6-29",
        "method": "왓츠앱",
        "content": "4학년 2학기때까지는 튜션을 과외를 했음. 그 다음에 로컬 진도로 했음. 지금 1년 조금 넘게, 아예 아무것도 안했다. 학교에 있는 수학만 하고 싶다고 해서. 그러고 놀다가 로컬 학원에 동생이 다니고 있는데, 거기를 다녀보자. 거기 테스트를 봤는데 레벨 테스트에 합격을 못했음. 학교수학은 UWC excellent, 높은 것 반, meet 되어 있는 것 반. 친구들이 학원에 많이 다니고 있어서 UWC Dover나 UWC East친구들 어머님들께서 추천을 많이 해주셔서 그냥 믿고 보내실 생각이라고 하셨음. 일단 학생이 3명이 모이지 않은 상황이라 더 모이면 그때 컨펌 드리기로 함. 아버님께서 매우 나이스 하셨고 딱히 질문은 없다고 하셨음. 수업 진행방식이나 커리큘럼에 대해서 소개해드렸음. 그리고 Local 학원 못들어가게 된 이유에 대해서는 모델링같은 것들이 있다보니 P6반은 어려웠을 수도 있다고 오지랖(?) 살짝 부렸음. 반 개설 확정되면 연락 드려야함."
      }
