      {
        "date": "2026-04-17",
        "method": "알 수 없음",
        "content": "안녕하세요 G9아이 수학 수업 수강해보려는데 가능할까요? 혹시 레벨 테스트 보시나요?"
      },
      {
        "date": "2026-4-30",
        "method": "카카오톡 보이스톡",
        "content": "친구들이 전부 여기 다니더라. KS에서 같이 다니고 있는 시안이, 스텔라 등이 스마트 학원을 추천해주어 연락하게 되었다고 함. 일단 G9 테스트는 96%가 나왔고 Topic Test는 10%가 나옴. 실력은 A반 실력이지만 현재 정원이 차 있어서 B반에서 수업을 듣고 A반에 대기 하다가 자리가 나면 옮기는 것을 권해드림. UWCD로 전학온지 얼마 안되었다고 함. 정보를 잘 모르고 하심. 학년을 높여 듣는 아이도 있다고 들으셨다고 해서 그런 경우도 있다고 말씀 드림. 레포트 보내드리면 아이와 상의해보고 결정해서 알려주시겠다고 함."
      }
