      {
        "date": "2026-4-21",
        "method": "카카오톡 보이스톡",
        "content": "작년 9월에 UWCD에 왔고 한국에서 온지 얼마 안됐음. 한국에서 수학을 해서 기본기가 탄탄함. G9 테스트 94%를 맞았으나 토픽테스트는 대부분 풀지 못함. 조금 의아한 포인트인데 어머님 설명 듣고 이해가 갔음. 다른 학교에서 6개월 듣고 UWCD로 G9 9월부터 시작했는데 수학은 Math Plus가 아니고 그냥 일반 수학을 듣고 있으며 10학년 올라갈 때 Math Plus로 올라갈 수 있게 된다고 함. 그래서 한국 수학은 다 하고 왔으나 싱가포르에 와서 심화 수학을 배우지 못해 토픽 테스트 점수가 저조했던 것. 만약 G9시작할 때 이 시험을 봤다면 바로 A반에 배정을 받았을거라고 말씀 드림. 현재는 G9 A반은 정원이 차 있고 진도도 상당히 나가 있는 상황이라고 말씀 드렸고 옵션은 G9 B반에 조인하거나 아니면 G9 Nov반(6개월 느리지만) 이 두가지를 드림. 진도는 G9 Nov반이 늦지만 반의 페이스는 빠른편이라 학생이 커버하지 못했던(trigo 포함) 토픽들을 Nov반에서 커버하고 있다가 나중에 A반에 자리가 나면 조인하면 좋겠다고 말씀 드림. 같은 학교 학생들이 학원에 많이 다니고 있고 A/B반 같은걸로 얘기를 많이 나누고 있다고. Nov반에 조인하게 되면 장단점 설명 추가로 드렸고 단점으로는 학기제가 달라 방학기간에 기간이 맞지 않아 수업을 듣지 못하게 되는 경우도 생길 수 있다는 점. 그리고 언젠가는 A/B반으로 넘어와야 한다고 말씀 드림. 어머님께서는 Nov반으로 마음 결정하신 것 같아 보였으나 학생하고 다시 한번 확인하고 연락 주시기로 함. 이번주는 학교 시험 대비를 시켜주기 때문에 다음주부터 조인하면 좋겠다고 말씀 드림."
      }
