    "notes": [
      {
        "date": "2023-09-09",
        "method": "카카오톡 보이스톡",
        "content": "25년7월23일 보톡: 방학동안에 nidhi 통해서 3주간 거의 매일 한시간씩 추가 수업을 해왔었고 업데이트 드리려 전화 드림. 다해가 테스트때 봐서 틀렸던 내용들 다시 복습하니까 잘 한다는 부분 전달드렸고 오히려 그보다 더 기초부분은 word problem, 예를 들면 2/3 of the dad's age 라고 했을 때 이걸 곱할지 더할지를 헷갈려 한다고 말씀 드림. 영어의 문제인지 아니면 영어로된 표현을 수학적으로 옮기는 부분의 문제인지는 정확히 모르겠다고 말씀 드렸더니 영어가 더 편한 아이어서 영어의 문제는 아닐거라고 말씀 하심. 그리고 어머님께서 다시 한번 테스트 보고 C반으로 옮길 수는 없는지 문의 하셔서 이미 HL을 할게 아닌게 결정이 되었다면 C반으로 가는것은 비효율적이라고 말씀 드림. IB SL가면 배우지 않을 내용들을 커버할 거라서 불필요하게 더 많이 배우게 되는 셈이라고 말씀 드림. 그리고 다음주에 지금까지 보충한 효과 어떤지 테스트를 다시 보기로 했었는데 테스트 결과를 보고 반 배정을 다시 해야할지 궁금해 하셨는데 그럴 필요가 없다고, 그냥 Extended Math반으로 가는게 좋겠다고 말씀 하심. 그리고 이전에 여자 선생님과 수업할 때 한국말이어서 좀 이해가 어려웠던 부분이 있었지만 그냥 지나쳤었다고 나중에서야 얘기를 했다고 함. Sun Yuan 선생님 수업이 잘 맞았다고 해서 마침 이번에 G9 Extende dMath반은 Sun Yuan 선생님이 맡게 된다고 말씀 드림. 훈훈하게 마무리."
      },
      {
        "date": "2023-09-09",
        "method": "카카오톡 보이스톡",
        "content": "25년8월8일 보톡: 재시험 결과 45%가 나와서 지난 시험보다 20% 가량 더 올라갔다고 알려드림. 그 사이에 좀 까먹어서 배웠던건데 못풀었던게 있지만 그래도 이정도면 G9 Extended Math시작하는데 있어서 크게 어려움은 없을 것이라고 말씀 드림. 어머님께서는 두명 밖에 없어서 반이 안만들어지는건 아닌지 문의하셔서 두명으로라도 출발 시킨다고 말씀 드림. 그리고 Add math로는 갈 필요 없겠죠? 물어보셔서 필요 없다고 말씀 드림. 잘 부탁드린다고 하시고는 전화 끊음. 이콘도 문의 하셔서 KS에 문의하시라고 알려드림."
      },
      {
        "date": "2023-09-09",
        "method": "카카오톡 보이스톡",
        "content": "25년9월29일 보톡: 숙제 제출이 계속 늦어지고 있다고 알려드림. 수업 바로 전날 올리다보니 채점을 제때 받지 못해 코렉션이 안되고 있다고 말씀드리고 룰이 있어서 다음번에 또 늦게 내면 남아서 하거나 다음날 와서 숙제 하고 가게 되어 있다고 말씀 드렸더니 괜찮다고 하심. 혹시 스케쥴상오지 못하는 상황인가 싶어서 여쭤본 것이었다고 말씀 드림."
      },
      {
        "date": "2023-09-09",
        "method": "문자",
        "content": "26년1월21일: 다해 선생님 바뀌고 난 후에 전반적인 피드백 드리려고 전화 드림. 수학은 잘 하는 편이고 금방 이해하고 문제도 잘 푼다고 말씀 드림. 다만 공부에 욕심이 많지 않아 보여 조금만 더 하면 잘 할 것 같은데 더 잘 할 필요성을 못느껴하는 것 같다고 말씀 드렸더니 공감하셨음. 학교 성적은 잘 나오고 있어서 본인도 딱히 더 잘하려고 안하는 것 같다고. 그리고 핸드폰 쓰는 문제 관련해서 말씀 드림. 핸드폰을 못쓰게 함에도 불구하고 10분마다 계속 핸드폰을 꺼나 알림을 확인하여 선생님께서 계속 주의를 줬지만 듣지 않고 꺼냈다고 말씀 드림. 어머님께서 더 strict하게 해야지 아이가 말을 들으거라고, 지금 사춘기라 좀 삐딱한게 있지만 엄격하면 선생님 말씀 들을 것이라고 하셨음. 선생님께도 전달 드림. 그 외에 숙제 같은건 제때 못내면 선생님께 죄송하다고 문자 보내면서 끝까지 책임지고 하려는 모습이 보인다고 말씀 드림. 어머님께서 피드백 주셔서 너무 감사하고 집에서 핸드폰 못쓰게 하는 것 관련해서 한번 더 주의 주시겠다고 하셨음."
      },
      {
        "date": "2023-09-09",
        "method": "카카오톡 보이스톡",
        "content": "26년5월7일 보톡: 어머님의 컴플레인. 정도를 좀 지나친 코멘트를 하셨음. 다른 학생이 5,6월 등록을 하지 않겠다고 하여 다해만 남은 상황인데 혹시 다해도 시험기간이라서 수업을 못오는 경우가 생길 수 있는지 여쭤봤더니 그 아이가 왜 나가는지 알겠다면서 컴플레인을 쏟아내심. 애가 성적이 안나오고 있다, 관리가 전혀 안되고 있다, 숙제도 제대로 안하는 것 같고, 이런식으로 코멘트를 주심. 애에 대해서 너무 신경을 안쓰시는 것 같다길래 조목조목 다 반박을 하였음. 매주 마다 미팅하면서 다해 어떻게 하고 있는지 내가 확인하고 있었고 숙제 제출도 매우 잘 하고 있고, 관리만 놓고 보면 지금 선생님이 관리면에서는 제일 레벨이 높다고 말씀 드렸더니 말을 바꾸심. 관리를 잘 해주시긴 했는데 애가 수학에 흥미를 가질 수 있게 해주는 것도 아니고, 뭐 선생님이 잘 가르친다 못가르친다를 얘기하는게 아니고, 그 전에 있던 아이들도 나가는데에는 이유가 있지 않겠냐. 지난번에 울면서 심하게 컴플레인하셨던 것 처럼 그냥 말을 쏟아내심. 선생님만 바뀌면 될 것 같다고 말씀 하심. 그리고 왜 수업을 그렇게 운영하시는지 이해가 안된다, 용준이 말로는 왜 Extended Math반에 들어가냐, add Math 반에 들어갔다가 나중에 SL 해도 되지 않느냐. 그렇게 해서 내리는 학생들도 많이 있는데 왜 다해는 그렇게 안시키는지 이해가 안된다. 이런식으로 말씀 하심. 이전에 이미 어머님과 충분히 상의 하였고 Add Math 가는 것 보다 Extended Math로 가는게 낫다고 판단하여 그렇게 결정하였고 지금도 같은 생각이다. Add Math하다가 SL로 내려간 아이들은 처음에는 HL을 하려고 시도했던 학생들이었기 때문에 Add Math를 듣게 했었던거고 다해처럼 처음부터 SL을 하기로 결정한 학생이면 처음부터 Extended Math로 가는걸로 권해드리고 있고 지금도 같은 생각이라고 말씀 드림. 애를 6학년때부터 계속 믿고 맡겼는데 이렇게 될 줄 알았으면 과외를 시켰을거라면서 자꾸 공격적으로 말씀 하심. 물론 용준이랑 다해가 다르고 아이들마다 다를 수 있지만... 이러시면서 톤다운을 하시기도 함."
      }
    ]
