        "content": "25년9월15일 보톡: 어머님과 20분간 통화. 아이 잘 하고 있냐고 해서 관찰한 것들 말씀 드림. 꼼꼼하게 알때까지 계속 질문하면서 챙겨 공부하는 습관이 잘 되어 있다. 하지만 문제 푸는데 시간이 다소 걸리고 새로운 것을 습득하는데 시간이 다소 걸린다고 말씀 드림. 어머님께서도 정확하게 짚으셨다고 하시면서 집에서 문제를 풀 때 두시간 세시간동안 끙끙 앓고 있는데 이게 맞는거냐고 하셔서 올바른 학습 방법이라고 말씀 드림. 이걸 풀기 위해 이것저것 찾아보고 배웠던 내용들 다시 인출하는 과정에서 복습이 되고 효율적인 학습 방법이라고. 하지만 이게 너무 오래 걸려서 다른 유형들을 풀어볼 기회가 없는데 이게 맞냐고 하셔서 좀 어려운 질문인 것 같다고 말씀 드림. 한가지를 위해 다른 것들을 공부 못하게 되면 그것도 좀 위험하니 적절하게 타협을 보는게 좋겠다고만 말씀 드림. 이번 시험 50점 만점에 28점이 나왔다고 함. 세 문제가 어려웠는데 sequence는 공부를 더 했었어야 하는데 안해서 그런거라고. 안그래도 속도가 느린데 공부를 시험 직전에 시작을 했다고 함. 문제 푸는 양이 충분해야 하는데 10학년때 생각하면서 공부를 하는 바람에 그렇게 됐다고 함. 원장님 말씀을 정말 잘 듣는다고 하면서 재한이에게 공부 방법좀 알려주면서 지도해달라고 하심. 저번 수업때 남아서 5분만 공부하고 가라고 했더니 남아서 공부하다가 11:30에 과학 수업을 들으러 갔다고. 이번에 시험지 받으면 같이 분석해보고 다음 공부 방법 및 수업 끝나고 남아서 어떻게 공부해야하는지 알려드리겠다고 말씀 드림."
