        "content": "이시안 학생은 G7이지만, paper 1의 결과가 약 76%, paper 2의 결과가 46%가 나온 것으로 보아 학년에 비해 선행이 비교적 많이 되어 있어보입니다. 물론 paper 2의 결과가 월등히 높지는 않지만, quadratic function의 vertex form, composite function 까지 푼 것을 보면 선행을 좀 한 친구입니다. 테스트 결과만을 봤을 때는 이 친구는 현재 G7반 보다는 G8이 더 적합해 보입니다. 그런데 현재 G8 반은 토요일 1자리만 남아있는데, 최근 테스트를 먼저 본 배채원(G7) 학생의 paper 1의 결과가 93%로 훨씬 좋습니다. 만약, 이 친구가  paper 2를 보고 결과 더 좋다면, 이 친구가 G8 토요일 반에 적합할 수도 있기 때문에 지금 반을 배정하기는 좀 애매한 상황입니다. 배채원 학생이 paper 2를 최대한 빨리 보게하고 하던지, 만약 배채원 학생이 paper 2가 어려워서 못푼다고 하면 이 친구는 G7 토요일 반으로 가면 되고, 이시안 학생은 G8 토요일반으로 가면 될 것 같습니다. 우선, 최근 시험 본 아래의 두학생이 결과와 틀린 것들이 굉장히 비슷합니다. 두 학생이 분명 어느 정도 선행한 것으로 보여지는데, 둘다 쉬운 quadratic factorization이 틀렸고, line graph perpendicular 개념이 잘 정리가 되어있지 않아 보입니다. indices(negative/fraction power)는 둘다 안되어 있어 보이네요. quadratic function의 vertex form을 배우긴 했는데 어떤 문제는 맞고, 어떤 문제는  틀린 것을 보면 개념 정리가 필요해 보입니다. 더욱이, scale factor도 둘다 틀렸는데요, 현재 위에서 언급한 토픽은 현재 G8 수요일, 토요일 반은 모두 진도가 나간 상태입니다. 그래서 어차피 학년이 어린 학생을 G8반으로 보내기 보다는 G7반 중에서 좀더 선행이 되어있는 토요일 반으로 편성을 같이 해서 두 학생을 좀더 관리하기 쉬울 것 같다는 판단이 들었습니다. 기존 토요일 G7반의 학생들이 자극을 받아서 좀더 잘하는 반으로 분위기를 끌어올릴 수도 있을 것 같구요.  또 다른 이유는 학년이 어린 두 학생을 학년을 올려서 G8 수업을 듣게 할 경우, 5월에 예비 G9반 편성고사를 볼 경우 두 친구는 나중에 저 토픽에서 점수차가 나서 좋지 않을 것 같다는 판단이 들었습니다."
