        "content": "8월20일 상담 드림. 박민채(G8) 학생 테스트 결과 paper 1은 78%, paper 2는 57% 으로 전반적으로 수학 기본기가 잘 되어 있어보입니다.  quadratic equation을 푼 것을 보면 factorisation을 아는 것으로 보이는데, 쉬운 문제(17번)을 틀렸네요. simultaneous inequalities도 틀린 것을 보면 조금만 정리하면 더 좋아보입니다. rationalization도 할 수 있고, variation 문제도 맞은 것을 보면 선행도 어느 정도 한 것 같습니다. exponent (fraction power), inverse function, quadratic function, circle theorem은 선행이 안되어 있어보입니다. 이 친구는G9 add math 반을 들을 수 있을 정도로 선행이 되어 있어 보이지는 않아요.   G8 B반 토요일이 괜찮을 것 같습니다. 학생의 수준을 보면 G9 extended math 반의 레벨도 괜찮을 것 같은데,  그 반 남학생들 보다는 토요일반 G8 학생들이 수업태도나 선행이 오히려 잘 되어 있어서 그 반이 오히려 괜찮을 것 같습니다. ----- 학생이 주말에만 수업이 가능해서 두 반 사이의 차이가 별로 없다면 토요일반에 자리 나면 알려달라고 하심. 현재 정원이 차 있다고 말씀드렸더니 얼만큼 기다려야 하는지 문의 하심. 현재로서는 알 수 없지만 새롭게 반이 개설되면 금방 자리가 날 수도 있고 아니면 9학년 될때까지 자리가 나지 않을 수도 있다고 말씀드림."
