        "content": "25년9월8일 방문 상담: 다른 어머님 두분과 같이 오심. 두 어머님 중에 한분은 이전에 스마트 학원에 문의 주신 적이 있었음. 이 어머님은 첫째가 G9이라서 SAS 커리큘럼에 대해서 잘 알고 계셨음. 알렉스 선생님이 고학년에 대한 얘기할 때 이건 이렇게 되고 있어요, 라고 중간에 끼어서 말씀하실정도로 어느정도 알고 계신듯. 세 학생 모두 노비나에 있는 Mat Plus Lit에서 로컬 수학으로 Pre Algebra를 다 배웠다고 했는데 어머님들도 이건 주장에 불과하고 아이들이 제대로 컨셉을 이해했을지 모르겠다고 의심하고 계심. 일단 5학년 수학은 다 배운것으로 보여지고 추후 테스트를 거쳐서 얼만큼 알고 있는지 확인을 먼저 하고 Pre algebra를 다시 할지 말지 결정하면 될 것 같다고 말씀 드림. 일단 현재 학원 반 운영 방식을 먼저 말씀 드렸고(8학년까지는 같이 섞여 듣다가 나중에 G9때부터는 학원을 옮기라 권해드리고 있다). 수학은 비슷하지만 진도 나가는 순서가 학교마다 달라 학교 수학을 준비한다기보다 공통수학을 배워나가는 거라고 보시면 된다고 말씀 드림. 하지만 SAS반을 열게 되면 학교 특성에 맞춰 나갈 수 있으니 학교 시험에도 도움이 될 수 있을거라고 말씀 드림. 일단 반을 열더라도 SAS나 스탬포드같이 미국 커리큘럼 하는 학생이 추가적으로 들어올 수 있다고 미리 말씀 드린다고 했음. 학원의 수업 시스템에 대해 설명 드림. 숙제 제출 3일 이내, 코렉션, 퀴즈 등등. ELC얘기도 살짝 하긴 했는데 이건 어린 아이들의 경우 관리자가 없을 때에는 아직 추천 드리지는 않는다고 말씀 드림. 수업 스타일은 원리를 많이 강조하고 아이들의 공부 습관을 잡아주는데에 있다고 말씀 드림. 어머님들이 좋아하심. 학원이 나아가고자 하는 방향에 대해 (아이들의 공부하는 힘을 길러주기) 긍정적으로 봐주셨고 바로 조인 가능한 시기부터 옮겼으면 한다고 하심. 저쪽 학원에 미리 얘기를 해야 한다고 함. 선생님의 available slots를 다시 한번 컨펌 하고 알려드리기로 함. 교재를 처음부터 만들어야 한다고 말씀 드렸더니 교재는 시중 교재 써도 괜찮다고 하심. 최대한 부담을 덜어주시려고 하셨음."
