        "method": "일반 전화",
        "content": "G9 레벨테스트 권유 전화. 어머님은 G9으로 갈거면 G9A반에 들어가는게 맞지 않은지 생각하심. 선행을 하는건데 레벨 낮은 반에서 천천히 나가는것은 의미가 없지 않냐고 하심. 일단 테스트를 보고 판단해볼수있는데 G9반은 진도도 다르다보니 가장 적절한 반으로 배정해주실 거라고 답변드림. 원장님 수업이 좋다는 얘기를 들으셨는데 A반이 알렉스선생님 반인거 보니 선생님도 좋으신가봐요?라고 물어보셔서 조인하신 이후에 반을 나눠서 맡고 있고 헤드튜터 맡고 계시고 학생들 잘 챙겨주시고 지도를 잘 해주신다고 말씀드림. 고2까지 마치진 않았고 고1을 했다.라고만 알고 있어달라고 하심."
