        "content": "26년2월2일 보톡: 학생이 원래 한국을 갈지 말지 결정이 안되었다가 이번에 남는걸로 결정되어서 빠르게 학원을 알아보고 있다고 하심. 다들 스마트 학원으로 난리라서 최대한 빨리 연락해서 반에 자리가 있는지 확인을 하고 싶으셨다고 하심. 오늘 당장 알수 있느냐길래 일단 IGCSE시험을 보는지 아닌지 여부 먼저 알려다라고 말씀 드렸고 내일 실장님 출근하면 답변 드리겠다고 함. 단톡방 열어서 아버님과 같이 전달 받고 싶다고 하심. 학생은 IB에 가서 AA HL Math를 할거라고 함. (정확히 명칭을 몰라 한국 아이들이 많이 하는 제일 높은 수학이라고 표현하심)"
