        "content": "전화문의. HL선택할거고 학교에서도 ADD MATH함.남녀비율 물어보심. 비율에 따라 분위기가 달라서 물어보셨다고 하심. 선생님은 Add math B,C반 둘다 ALEX 선생님이신가요? 물어보시고 정원, 수업시간, 수업료 안내 받으심. 11학년 수업듣는 10학년도 있던데 가능한건지 여쭤보셔서 레벨테스트 봐야 판단 가능하다고 말씀드림. Extended math 공통수학 보통 SL 선택, Add math 이과수학 보통 HL 선택하는 학생들이 한다고 설명 드림. 학원에 대해 어느정도는 알고 계신 느낌. 반에 UWCD 여학생 누구 있는지 여쭤보셔서 말씀드리지 않음. 반별 차이 여쭤보셔서 D반은 9학년 때 Add math 하지 않은 아이들이 처음부터 배워가고 있는 반이고 C반은 학원 자체 커리큘럼으로 9학년때부터 이어져온 반으로 진도 내용이 다르진 않고 속도가 다르다고 말씀드림. 학생과 레벨테스트 날짜 상의 후 다시 연락주겠다고 하심. 카톡으로 안내주시면 더 빨리 문의 확인이 가능하다고 답변 드림."
