        "content": "26년4월12일 보톡: 좋은 피드백. 영어 수업임에도 불구하고 학생이 이해하기 쉬웠다고 얘기함. 어머님께서는 이미 다 알고 있는 걸 배워서 쉽다고 얘기한건지, 아니면 몰랐거나 약했던 부분인데 선생님의 수업으로 쉽게 이해했다는 것인지 구분이 안된다고 하셨음. 레벨 테스트에서 틀린 부분을 배웠던건지 맞춘 부분을 배웠떤건지 물어보셔서 틀린 부분이라고 했더니 그러면 바로 남은 수업들도 조인하시겠다고 하셨음. 아무래도 G8인데 G7반에조인하는 것이라 어머님께서 계속 조심스러워 하심. 곧 삼각함수 시험보는데 이걸 복습할 수 있을지 여쭤보셔서 이미 저번달에 커버했었는데 복습을 할 예정인지 확인해보고 알려드리겠다고 말씀 드림. 그리고 아이가 약한 토픽들 리스트 보내주면 학원에서 복습 가능한지 물어보셔서 일단 리스트 선생님께 보내주시면 선생님께서 상황 보고 토픽 순서를 바꿀 수 있으면 바꾸실거라고, 안될수도 있다고 말씀 드림."
