        "content": "26년4월14일 전화로 문의 주심. 학교에서는 Advanced 반에 있는데 주위에서 하도 IB준비를 빨리 시작해야되고 스마트 학원 가라고 얘기하고 있어서 문의 주셨다고 함. 딸하고 얘기해보고 테스트 먼저 보내고 이후에 일요일 6:20에 상담 오시기로 함."
